-- 0063_challenge_sim_ledger_ad_auth_enum.sql: fills the remaining 2 gaps in
-- the "challenge_sim" self-practice set from 0051 -- "Ledger" (THM, Web/Auth
-- IDOR) and "AD Authenticated Enumeration" (THM, Active Directory) both have
-- a verified writeup_url in pentestChallenges.ts but were missed in the
-- original batch. Same mechanism/caveats as 0051: technique/methodology-level
-- questions only (never literal flags/IPs), rendered via the existing
-- "Lam Simulation" UI in Labs.vue, not part of the FSRS queue. ON CONFLICT
-- preserves any user-authored card with the same front text untouched.

INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'lab', c.front, c.payload::jsonb, 'seed'
FROM (VALUES
  ('[Simulation] THM — Ledger', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Ledger\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Để kiểm tra lỗ hổng kiểm soát truy cập trên một tính năng xem hồ sơ/đơn hàng theo ID (ví dụ /invoice/1024), phương pháp test có hệ thống nhất là gì: tạo 1 tài khoản rồi đoán ID, hay làm theo cách khác?", "patterns": ["2\\s*t[àa]i\\s*kho[ảa]n", "a\\s*/\\s*b", "tài khoản a.*tài khoản b"], "explanation": "Cách test chuẩn là tạo 2 tài khoản A và B, lấy ID tài nguyên của A, rồi dùng session của B gọi API với ID đó — nếu B xem/sửa được dữ liệu của A nghĩa là có lỗi kiểm soát truy cập (IDOR), tránh nhầm với việc chỉ đoán ID ngẫu nhiên trên 1 tài khoản.", "hint": "Cần ít nhất 2 tài khoản khác nhau để chứng minh được lỗi, không chỉ 1 tài khoản."}, {"prompt": "Khi ID tài nguyên trong URL/API là số tăng dần tuần tự (1024, 1025, 1026...) thay vì UUID ngẫu nhiên, điều này làm tăng rủi ro cho loại lỗ hổng truy cập trái phép nào?", "patterns": ["idor", "insecure direct object reference"], "explanation": "ID tuần tự dễ đoán khiến kẻ tấn công chỉ cần tăng/giảm số để dò ra tài nguyên của người khác — đây là điều kiện thuận lợi cho IDOR (Insecure Direct Object Reference), so với ID dạng UUID ngẫu nhiên khó đoán hơn.", "hint": "Loại lỗ hổng khi object được tham chiếu trực tiếp qua ID mà không kiểm tra quyền sở hữu."}, {"prompt": "Nếu request đăng ký/cập nhật hồ sơ gửi lên server có thêm một trường ẩn (ví dụ role hoặc is_admin) không hiển thị trên UI, nhưng server vẫn đọc và gán giá trị đó vào bản ghi người dùng, đây là lớp lỗ hổng gì?", "patterns": ["mass assignment", "over[- ]?posting"], "explanation": "Mass Assignment xảy ra khi backend tự động gán toàn bộ field trong JSON/form request vào object dữ liệu mà không giới hạn (whitelist) field nào người dùng được phép tự đặt, cho phép leo quyền bằng cách thêm field như role=admin.", "hint": "Lỗi liên quan tới việc server gán luôn mọi trường gửi lên, kể cả trường nhạy cảm không có trên UI."}, {"prompt": "Sau khi đăng nhập thành công, nếu bạn thay đổi giá trị của cookie/token session (ví dụ sửa 1 ký tự hoặc decode rồi sửa payload của JWT) và server vẫn chấp nhận với quyền cao hơn, lỗ hổng xác thực này liên quan tới điều gì?", "patterns": ["jwt", "token.*(không.*k[iý] |không verify)", "signature", "x[áa]c\\s*th[ựu]c\\s*token"], "explanation": "Đây là lỗi xác thực token/session: nếu server không verify đúng chữ ký (signature) của JWT hoặc không kiểm tra tính toàn vẹn của session token, kẻ tấn công có thể tự sửa claim (ví dụ role, user id) để leo quyền.", "hint": "Liên quan tới việc server không kiểm tra đủ chặt tính hợp lệ của token sau khi bị chỉnh sửa."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Ledger"}'),
  ('[Simulation] THM — AD Authenticated Enumeration', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"AD Authenticated Enumeration\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Khi đã có 1 bộ username/password domain hợp lệ (khác với trường hợp null session), công cụ nào cho phép liệt kê nhanh user, group VÀ share SMB cùng lúc trên Domain Controller chỉ với một lệnh (ví dụ netexec/crackmapexec)?", "patterns": ["netexec", "crackmapexec", "\\bcme\\b", "\\bnxc\\b"], "explanation": "netexec (hậu duệ của crackmapexec) với creds hợp lệ cho phép liệt kê users/groups/shares trên SMB chỉ với 1 lệnh (--users --groups --shares), nhanh hơn nhiều so với từng công cụ riêng lẻ như net user.", "hint": "Công cụ post-exploitation AD phổ biến, viết tắt 3-4 chữ, kế nhiệm crackmapexec."}, {"prompt": "Để truy vấn trực tiếp cấu trúc LDAP của domain (OU, user attributes, group membership) khi đã có credential, thay vì dùng GUI Active Directory Users and Computers, công cụ dòng lệnh Linux nào thường dùng để query LDAP?", "patterns": ["ldapsearch", "windapsearch"], "explanation": "ldapsearch (hoặc windapsearch) cho phép truy vấn trực tiếp LDAP server của AD bằng credential đã có, lấy được thông tin user/group/OU chi tiết mà không cần máy Windows join domain.", "hint": "Công cụ Linux để gửi truy vấn LDAP trực tiếp tới Domain Controller."}, {"prompt": "Với PowerShell trên một máy đã join domain (hoặc qua RDP/WinRM với credential hợp lệ), module/cmdlet nào cho phép truy vấn linh hoạt thông tin user, group membership và domain policy (ví dụ Get-ADUser, Get-ADGroupMember)?", "patterns": ["get-aduser", "get-adgroupmember", "active directory module", "rsat"], "explanation": "Module ActiveDirectory của PowerShell (RSAT) cung cấp các cmdlet như Get-ADUser, Get-ADGroupMember, Get-ADDomain để truy vấn linh hoạt thông tin domain khi đã đăng nhập với credential hợp lệ.", "hint": "Bộ cmdlet PowerShell chuyên dùng để truy vấn Active Directory, bắt đầu bằng Get-AD..."}, {"prompt": "Để thu thập toàn bộ dữ liệu quan hệ AD (session, ACL, group lồng nhau) phục vụ phân tích đường leo thang bằng BloodHound khi đã có 1 credential domain, công cụ thu thập (collector) chạy trên Linux/attack box (không cần máy join domain) tên là gì?", "patterns": ["bloodhound-python", "bloodhound\\.py"], "explanation": "bloodhound-python là bản collector chạy trên Linux, dùng credential hợp lệ (-u -p -d -ns) để thu thập dữ liệu AD qua LDAP/SMB rồi xuất ra JSON nạp vào BloodHound GUI để phân tích đường leo thang quyền.", "hint": "Phiên bản collector BloodHound chạy được từ máy Linux/Kali, không cần SharpHound trên Windows."}, {"prompt": "Khi đã có credential của 1 user thường, bạn muốn liệt kê các tài khoản service có SPN (Service Principal Name) để chuẩn bị tấn công Kerberoasting. Script Impacket nào dùng để truy vấn và request TGS cho các SPN đó?", "patterns": ["getuserspns", "get-adu.*spn"], "explanation": "GetUserSPNs.py (Impacket) dùng credential domain hợp lệ để liệt kê các account có SPN và request TGS cho chúng ở dạng crackable offline bằng hashcat — bước chuẩn bị cho Kerberoasting.", "hint": "Script trong Impacket chuyên liệt kê & request TGS cho các tài khoản có SPN."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1"], "challenge_key": "THM:AD Authenticated Enumeration"}')

) AS c(front, payload)
JOIN decks d ON d.slug = 'labs'
ON CONFLICT (deck_id, kind, lower(front)) DO NOTHING;
